CREATE TRIGGER audit_checkpoints_append_only BEFORE UPDATE OR DELETE ON whitetower.audit_checkpoints
  FOR EACH ROW EXECUTE FUNCTION whitetower.reject_change();
CREATE TRIGGER audit_checkpoints_no_truncate BEFORE TRUNCATE ON whitetower.audit_checkpoints
