CREATE TRIGGER lifecycle_transitions_append_only BEFORE UPDATE OR DELETE ON whitetower.lifecycle_transitions
  FOR EACH ROW EXECUTE FUNCTION whitetower.reject_change();
CREATE TRIGGER lifecycle_transitions_no_truncate BEFORE TRUNCATE ON whitetower.lifecycle_transitions
