CREATE TRIGGER use_case_decisions_append_only BEFORE UPDATE OR DELETE ON whitetower.use_case_decisions
  FOR EACH ROW EXECUTE FUNCTION whitetower.reject_change();
CREATE TRIGGER use_case_decisions_no_truncate BEFORE TRUNCATE ON whitetower.use_case_decisions
