-- Privileges of the runtime role -----------------------------------------------------------
-- Listed table by table on purpose: nothing is granted by default.

GRANT SELECT, INSERT, UPDATE ON
  whitetower.principals, whitetower.role_bindings, whitetower.api_tokens,
  whitetower.use_cases, whitetower.agents, whitetower.agent_owners, whitetower.ownership_transfers,
  whitetower.reviews, whitetower.signing_keys, whitetower.modules, whitetower.machine_credentials,
  whitetower.workload_issuers, whitetower.workload_identity_bindings,
  whitetower.policies, whitetower.policy_versions,
  whitetower.module_agent_bindings, whitetower.module_instances, whitetower.instance_agents,
  whitetower.governance_state, whitetower.halts, whitetower.halt_acks, whitetower.halt_release_requests,
  whitetower.audit_source_sequences, whitetower.audit_export_cursors,
  whitetower.settings, whitetower.job_state, whitetower.inbox_items
  TO whitetower_runtime;

-- Append-only for the runtime role.
GRANT SELECT, INSERT ON
  whitetower.use_case_decisions, whitetower.lifecycle_transitions,
  whitetower.policy_approvals, whitetower.policy_bundles,
  whitetower.audit_events, whitetower.audit_event_ids, whitetower.audit_leaves,
  whitetower.audit_tree_hashes, whitetower.audit_checkpoints
  TO whitetower_runtime;

-- Short-lived operational data that jobs clean up.
GRANT SELECT, INSERT, UPDATE, DELETE ON
  whitetower.sessions, whitetower.used_assertions, whitetower.outbox
  TO whitetower_runtime;

GRANT SELECT, UPDATE ON whitetower.fleet_state TO whitetower_runtime;
GRANT USAGE ON SEQUENCE whitetower.governance_state_version_seq TO whitetower_runtime;
GRANT EXECUTE ON FUNCTION whitetower.ensure_audit_partitions(integer) TO whitetower_runtime;
